                }
                host: {
                  connection: {
                    name: '@parameters(\'$connections\')[\'azuresentinel\'][\'connectionId\']'
                  }
                }
                method: 'post'
                path: '/Incidents/Comment'
              }
            }
          }
          else: {
            actions: {}
          }
          runAfter: {}
        }
      }
      outputs: {}
    }
    parameters: {
      '$connections': {
        value: {
          azuresentinel: {
            connectionId: sentinelConnection.id
            connectionName: sentinelConnection.name
            connectionProperties: {
              authentication: {
                type: 'ManagedServiceIdentity'
              }
            }
            id: sentinelManagedApiId
          }
        }
      }
    }
  }
}

resource workflowSentinelResponder 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(workspace.id, workflow.id, sentinelResponderRoleId)
  scope: workspace
  properties: {
    roleDefinitionId: sentinelResponderRoleId
    principalId: workflow.identity.principalId
    principalType: 'ServicePrincipal'
  }
}

resource sentinelAutomationContributor 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(resourceGroup().id, sentinelServicePrincipalObjectId, sentinelAutomationContributorRoleId)
  properties: {
    roleDefinitionId: sentinelAutomationContributorRoleId
    principalId: sentinelServicePrincipalObjectId
    principalType: 'ServicePrincipal'
  }
}

resource automationRule 'Microsoft.SecurityInsights/automationRules@2024-03-01' = {
  name: automationRuleId
  scope: workspace
  properties: {
    displayName: 'Identity client triage'
    order: 100
    triggeringLogic: {
      isEnabled: true
      triggersOn: 'Incidents'
      triggersWhen: 'Created'
      conditions: [
        {
          conditionType: 'Property'
          conditionProperties: {
            propertyName: 'IncidentRelatedAnalyticRuleIds'
            operator: 'Contains'
            propertyValues: analyticRuleIds
          }
        }
      ]
    }
    actions: [
      {
        order: 1
        actionType: 'RunPlaybook'
        actionConfiguration: {
          logicAppResourceId: workflow.id
          tenantId: tenant().tenantId
        }
      }
    ]
  }
  dependsOn: [
    workflowSentinelResponder
    sentinelAutomationContributor
  ]
}

output workflowResourceId string = workflow.id
output workflowPrincipalId string = workflow.identity.principalId
output automationRuleResourceId string = automationRule.id
output mode string = 'conditional-auto-close'


